# prepare normalized shape coords with source colors and exact-cover placements
shapes=[]
for co in comps:
 mr=min(r for r,c in co);mc=min(c for r,c in co)
 sh={(r-mr,c-mc):grid[r+10][c] for r,c in co}
 shapes.append(sh)
placements=[]
for sh in shapes:
 h=max(r for r,c in sh)+1; w=max(c for r,c in sh)+1
 pl=[]
 for dr in range(9-h+1):
  for dc in range(20-w+1):
   cells=frozenset((r+dr,c+dc) for r,c in sh)
   if cells <= mask:
    pl.append((dr,dc,cells))
 placements.append(pl)
print([len(x) for x in placements])

# exact-cover search for shape tiling; stop after first 20 solutions
allcells=sorted(mask); ci={p:i for i,p in enumerate(allcells)}
# each placement represented bitmask
pbits=[]
for i,pls in enumerate(placements):
 pbits.append([(dr,dc,cells,sum(1<<ci[x] for x in cells)) for dr,dc,cells in pls])
cover_options={p:[] for p in mask}
for i,pls in enumerate(pbits):
 for pl in pls:
  for p in pl[2]: cover_options[p].append((i,pl))
solutions=[];nodes=0

def search(occ, used, chosen):
 global nodes
 nodes+=1
 if len(solutions)>=20:return
 if len(occ)==len(mask):
  if len(used)==len(shapes): solutions.append(chosen.copy())
  return
 best=None; candbest=None
 for p in mask-occ:
  cand=[]
  for i,pl in cover_options[p]:
   if i not in used and not (pl[3] & sum(1<<ci[x] for x in occ)):
    # symmetric singleton ordering: at most one of comps 3,7 placed; use component 3 before 7, enforce coords
    if i==7 and 3 not in used: continue
    if i==7 and 3 in used:
     p3=next((x for x in chosen if x[0]==3),None)
     if p3 and (pl[0],pl[1]) < (p3[1][0],p3[1][1]): continue
    cand.append((i,pl))
  if not cand:
   return
  if candbest is None or len(cand)<len(candbest):
   best=p;candbest=cand
   if len(cand)==1:break
 occbits=sum(1<<ci[x] for x in occ)
 for i,pl in candbest:
  if i in used:continue
  if pl[3]&occbits:continue
  # process
  chosen.append((i,pl))
  search(occ|set(pl[2]), used|{i}, chosen)
  chosen.pop()
search(set(),set(),[])
print('nodes',nodes,'solutions',len(solutions))
